from pathlib import Path
p=Path(__file__).with_name('index.html')
s=p.read_text(encoding='utf-8')
script=s[s.index('<script>'):]
controls=s[s.index('<aside class="controls">'):s.index('</aside>')+8]
controls=controls.replace('<h2>遮罩设置</h2>','<div class="panel-title">遮罩检查器 <span>INSPECTOR</span></div><h2>自动打码</h2>')
controls=controls.replace('分析完成后自由多选部位、切换样式与强度。预览与导出分开，不为每种组合预生成视频。','选择需要保护的内容，所有效果均带柔和边缘渐变。')
controls=controls.replace('<button id="exportBtn"', '<button id="exportBtn"')
scrub=s[s.index('<div id="scrubber"'):s.index('<div class="stage-footer"')]
progress=s[s.index('<div id="progressWrap"'):s.index('</div><aside class="controls">')]
css='''
:root{color-scheme:dark;--bg:#101114;--panel:#1b1d22;--ink:#e5e7ec;--muted:#9096a3;--line:#2d3038;--accent:#b8ed80}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:var(--bg);color:var(--ink);font:13px/1.5 "Segoe UI","Microsoft YaHei",sans-serif}button,input,a,label{font:inherit}button,a,label[for=file],summary{ -webkit-tap-highlight-color:transparent}button{cursor:pointer}button:disabled{cursor:default;opacity:.38}button:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.shell{height:100vh;min-height:740px;display:grid;grid-template-rows:58px minmax(0,1fr) 26px;padding:0 14px;gap:10px}header{display:flex;align-items:center;gap:24px;border-bottom:1px solid var(--line)}.brand{font-size:15px;font-weight:650;letter-spacing:2px;display:flex;align-items:center;gap:10px}.mark{width:26px;height:26px;border-radius:7px;background:var(--accent);color:#172212;display:grid;place-items:center;font-size:18px}.project-title{border-left:1px solid var(--line);padding-left:24px;color:var(--muted);font-size:12px}.top-note{margin-left:auto;font-size:11px;color:var(--muted)}.workspace{min-height:0;display:grid;grid-template-columns:220px minmax(320px,1fr) 310px;grid-template-rows:minmax(300px,1fr) 220px;gap:10px}.media-panel,.stage,.controls,.timeline{border:1px solid var(--line);border-radius:9px;background:var(--panel);min-width:0;min-height:0}.panel-title{height:43px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;font-weight:600;font-size:12px;padding:0 15px}.panel-title span{font-size:9px;color:var(--muted);letter-spacing:1.2px;font-weight:400}.media-panel{padding-bottom:16px;overflow:auto}.media-inner{padding:14px}.secondary,.primary{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;border:1px solid #424651;background:#292c34;border-radius:5px;color:var(--ink);padding:8px 12px;cursor:pointer;font-size:12px}.import-button{width:100%;border-color:#657b4f;background:#283420;color:#d5f9b2}.media-item{margin-top:16px;border:1px solid var(--line);border-radius:6px;padding:15px 12px;background:#15171c}.media-icon{display:block;font-size:24px;color:var(--muted);margin-bottom:22px}.file-name{display:block;overflow-wrap:anywhere;font-size:12px}.media-caption{font-size:10px;color:var(--muted);margin-top:6px}.workflow{margin:24px 0 0;padding:0;list-style:none;counter-reset:step}.workflow li{display:flex;gap:10px;color:var(--muted);font-size:11px;padding:8px 0}.workflow li:before{counter-increment:step;content:counter(step);border:1px solid #424651;border-radius:50%;width:18px;height:18px;display:grid;place-items:center;font-size:10px;flex-shrink:0}.local-card{margin-top:20px;border-top:1px solid var(--line);padding-top:15px;font-size:11px;color:var(--muted)}.local-card strong{display:block;color:#cbd6c2;font-weight:500;margin-bottom:4px}.stage{display:flex;flex-direction:column;overflow:hidden}.stage-bar{height:43px;flex-shrink:0;display:flex;align-items:center;justify-content:space-between;padding:0 14px;border-bottom:1px solid var(--line);font-size:11px;color:var(--muted);gap:8px}.pill{font-size:10px;color:#b4c6a7;white-space:nowrap}.viewer{position:relative;flex:1;min-height:0;background:#090a0c;display:grid;place-items:center;overflow:hidden}.viewer video,.viewer img,.viewer canvas{position:absolute;width:100%;height:100%;object-fit:contain}.drop{padding:34px;text-align:center;cursor:pointer;max-width:390px;color:var(--muted);z-index:1}.drop-symbol{display:block;margin:0 auto 18px;width:60px;height:52px;border:1px solid #40464e;border-radius:9px;font-size:28px;color:var(--accent);line-height:50px}.drop strong{display:block;font-size:17px;font-weight:500;color:#dde1e8;margin-bottom:8px}.drop small{display:block;font-size:11px;margin-top:20px;color:#69717e}.viewer-note{position:absolute;bottom:14px;left:14px;right:14px;padding:9px 12px;background:#222832e8;font-size:12px;border-radius:4px;z-index:2}.stage-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 14px;min-height:39px;font-size:11px;color:var(--muted)}.status{display:flex;align-items:center;gap:7px;min-width:0}.dot{width:6px;height:6px;background:#6b7382;border-radius:50%;flex-shrink:0}.dot.ready{background:var(--accent)}.dot.busy{background:#e7bd78}.controls{grid-column:3;grid-row:1/3;overflow:auto;padding:0 18px 20px}.controls>.panel-title{margin:0 -18px}.controls h2{font-size:17px;margin:18px 0 5px;font-weight:550}.intro,.note,.export-note,.fineprint{font-size:11px;color:var(--muted);line-height:1.7}.intro{margin:0 0 22px}.group{margin:20px 0}.label{display:flex;align-items:center;justify-content:space-between;font-size:12px;margin-bottom:10px}.label span+span,.label output{color:var(--accent);font-variant-numeric:tabular-nums}.seg{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.seg button{border:1px solid #363a44;background:#252831;color:#b0b5c0;border-radius:5px;font-size:12px;padding:9px 3px}.seg button.active{background:#303e27;color:#d4f7b2;border-color:#718e56}.primary{background:var(--accent);border-color:var(--accent);color:#192112;font-weight:650;width:100%;margin-top:20px}.primary:disabled{background:#414738;border-color:#414738}.controls #download{width:100%;margin-top:8px}.advanced{border-top:1px solid var(--line);padding-top:17px;margin-top:22px}.advanced summary{font-size:12px;color:#b5bac5;cursor:pointer}.fineprint{border-top:1px solid var(--line);padding-top:14px;margin-top:20px;font-size:10px}.threshold-status{font-size:10px}.note{margin:8px 0}input[type=range]{accent-color:var(--accent);width:100%;cursor:pointer;height:14px}.timeline{grid-column:1/3;grid-row:2;overflow:auto;padding:0 16px 12px}.timeline>.panel-title{margin:0 -16px;height:36px}.timeline-head{display:flex;align-items:center;gap:8px}.timeline-head .secondary{padding:3px 9px;font-size:11px}.scrubber{padding-top:10px}.frame-meta{display:flex;align-items:center;gap:10px;font-size:11px}.frame-meta>label{display:none}.frame-meta>span{margin-left:auto;font-family:Consolas,monospace;color:#c8d0dc}.frame-meta button{padding:5px 16px}.scrubber>.note{font-size:10px;margin:6px 0;line-height:1.5}.track{height:39px;display:flex;align-items:center;gap:12px;margin-top:6px}.track-label{width:68px;flex-shrink:0;font-size:10px;color:var(--muted)}.track-clip{flex:1;height:28px;border:1px solid #4a654d;background:repeating-linear-gradient(90deg,#263c30 0px,#263c30 39px,#304a3a 40px,#304a3a 41px);border-radius:4px;font-size:10px;color:#c4decb;padding:5px 10px;white-space:nowrap;overflow:hidden}.track-clip.mask{background:#343b28;border-color:#647448;color:#d1e6b1}.timeline-empty{padding:24px 0;color:var(--muted);font-size:12px;text-align:center}.timeline-empty small{display:block;font-size:10px;margin-top:5px}.progress-wrap{padding:10px 14px;border-top:1px solid var(--line)}.progress-head{display:flex;justify-content:space-between;font-size:11px}.progress{height:3px;background:#30353d;border-radius:4px;margin:7px 0}.progress i{display:block;height:100%;background:var(--accent)}.progress-meta{color:var(--muted);font-size:10px}.bottom-note{margin:0;font-size:10px;color:#727b88;display:flex;justify-content:space-between;gap:10px}.editor-hint{color:#8a949f}.timeline #frameSlider{display:block;margin:7px 0}.transport-button{background:transparent;border:1px solid #444b57;border-radius:4px;padding:5px 10px;color:var(--ink)}
@media(min-width:1500px){.workspace{grid-template-columns:250px minmax(400px,1fr) 335px}}@media(max-width:1050px){.workspace{grid-template-columns:170px minmax(260px,1fr) 280px}.shell{padding:0 8px}.top-note{display:none}.controls{padding:0 12px 16px}.controls>.panel-title{margin:0 -12px}.project-title{font-size:10px}.media-inner{padding:10px}}@media(max-width:800px){.shell{height:auto;min-height:100vh}.workspace{display:flex;flex-direction:column}.media-panel{order:0}.media-inner{display:flex;align-items:center;gap:12px}.media-item{margin:0;padding:8px;flex:1}.media-icon,.workflow,.local-card,.media-caption{display:none}.import-button{width:auto}.stage{height:430px;order:1}.timeline{order:2;min-height:220px}.controls{order:3}.bottom-note{padding-bottom:10px;display:block}.project-title{margin-left:auto;border:0;padding:0}.brand{font-size:12px}.controls .seg{grid-template-columns:repeat(3,1fr)}}
'''
body='''<body><main class="shell">
<header><div class="brand"><span class="mark">◧</span>隐映 <span style="font-size:9px;color:var(--muted);letter-spacing:1px">INKSHIELD</span></div><div class="project-title">视频隐私工作台 / 本地项目</div><div class="top-note">本机处理 · 一次分析 · 即时调整</div></header>
<section class="workspace">
<aside class="media-panel"><div class="panel-title">素材库 <span>MEDIA</span></div><div class="media-inner"><label class="secondary import-button" for="file">＋ 导入视频</label><input id="file" type="file" accept="video/*" hidden><div class="media-item"><span class="media-icon">▻</span><span id="fileName" class="file-name">尚未导入素材</span><div id="mediaInfo" class="media-caption">导入一个视频开始处理</div></div><ol class="workflow"><li>导入视频，自动分析</li><li>选择部位，调整效果</li><li>逐段检查，导出成片</li></ol><div class="local-card"><strong>● 本地隐私处理</strong>视频与检测结果留在本机。<br>切换效果无需重新分析。</div></div></aside>
<div class="stage"><div class="stage-bar"><span id="previewMode">播放器 / 等待素材</span><span id="modelPill" class="pill">连接本地服务…</span></div><div id="viewer" class="viewer empty"><video id="source" controls playsinline hidden></video><img id="preview" alt="当前帧的打码效果" hidden><canvas id="playbackCanvas" aria-label="静音遮罩视频预览" hidden></canvas><div id="previewFeedback" class="viewer-note" role="status" hidden></div><label id="drop" class="drop" for="file"><span class="drop-symbol">＋</span><strong>从一段视频开始</strong><span>点击导入本地视频，自动分析人脸部位与车牌</span><small>原视频保留 · 效果可随时调整 · 全部遮罩边缘渐变</small></label></div><div class="stage-footer"><div class="status" role="status"><i id="statusDot" class="dot"></i><span id="statusText">等待导入视频</span></div><button id="retryAnalysis" class="secondary" type="button" hidden>重试分析</button></div>'''+progress+'''</div>
'''+controls+'''
<section class="timeline"><div class="panel-title">时间线 <span>FRAME REVIEW · 1×</span></div><div id="timelineEmpty" class="timeline-empty">分析完成后，在这里播放与逐帧检查<small>时间线用于检查整段视频；当前版本不提供剪切与多素材拼接。</small></div>'''+scrub.replace('<label for="frameSlider">逐帧检查</label>','<label for="frameSlider">逐帧检查</label><button id="prevFrame" class="transport-button" type="button" aria-label="上一帧" title="上一帧 · ←">❘‹</button>').replace('<span id="frameLabel">','<button id="nextFrame" class="transport-button" type="button" aria-label="下一帧" title="下一帧 · →">›❘</button><span id="frameLabel">')+'''<div id="timelineTracks" hidden><div class="track"><span class="track-label">V1 · 视频</span><div id="videoClip" class="track-clip">原视频</div></div><div class="track"><span class="track-label">M1 · 遮罩</span><div id="maskClip" class="track-clip mask">头部 · 马赛克 · 边缘渐变</div></div></div></section>
</section><footer class="bottom-note"><span>请检查漏检与柔边透出 · 导出为无声 MP4 · 原视频与缓存保留在本机</span><span class="editor-hint">空格 播放 / 暂停　← → 逐帧</span></footer></main>
'''
# Keep the proven processing paths; add view-only synchronisation and transport controls.
extra='''
function syncEditor(){const ready=analysisReady;$('#timelineEmpty').hidden=ready;$('#timelineTracks').hidden=!ready;$('#prevFrame').disabled=!ready;$('#nextFrame').disabled=!ready;$('#videoClip').textContent=selectedFile?selectedFile.name:'原视频';$('#maskClip').textContent=targetSummary(settings.targets)+' · '+styleNames[settings.style]+' · 边缘渐变';$('#mediaInfo').textContent=ready?frames+' 帧 · '+fps.toFixed(2)+' FPS':analyzing?'正在分析全部七类目标…':'导入一个视频开始处理'}
function stepFrame(delta){if(!analysisReady)return;stopPlayback();needsSeek=true;$('#frameSlider').value=String(Math.max(0,Math.min(frames-1,Number($('#frameSlider').value)+delta)));schedulePreview(0)}
$('#prevFrame').addEventListener('click',()=>stepFrame(-1));$('#nextFrame').addEventListener('click',()=>stepFrame(1));
document.addEventListener('keydown',event=>{const el=event.target;if(event.ctrlKey||event.altKey||event.metaKey||el.isContentEditable||['INPUT','TEXTAREA','SELECT','BUTTON','SUMMARY','A'].includes(el.tagName))return;if(event.code==='Space'&&analysisReady&&playback){event.preventDefault();if(playing||startingPlayback)stopPlayback();else startPlayback()}else if(event.key==='ArrowLeft'||event.key==='ArrowRight'){if(!analysisReady)return;event.preventDefault();stepFrame(event.key==='ArrowLeft'?-1:1)}});
const editorObserver=new MutationObserver(syncEditor);editorObserver.observe($('#statusText'),{childList:true,characterData:true,subtree:true});editorObserver.observe($('#targetNote'),{childList:true,characterData:true,subtree:true});document.querySelectorAll('.seg button').forEach(button=>button.addEventListener('click',syncEditor));syncEditor();
'''
script=script.replace("window.addEventListener('beforeunload'",extra+"\nwindow.addEventListener('beforeunload'")
p.write_text('<!doctype html>\n<html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>隐映 · 视频隐私工作台</title><style>'+css+'</style></head>\n'+body+script,encoding='utf-8')
print('Editor layout written; backend request and rendering code preserved.')
